TIER_RULES = {
    "bronze": (0.00, 10.0),
    "silver": (0.05, 5.0),
    "gold": (0.10, 0.0),
    "platinum": (0.15, 0.0),
}

def calculate_invoice(tier, amount):
    key = tier.lower()
    if key not in TIER_RULES:
        return "UNKNOWN_TIER"
    if amount < 0:
        return "INVALID_AMOUNT"
    disc_rate, ship_fee = TIER_RULES[key]
    discounted = amount * (1.0 - disc_rate)
    shipping = 0.0 if discounted >= 100.0 else ship_fee
    return f"Final:{discounted + shipping:.2f}"

n = int(input().strip())
for _ in range(n):
    t_s, a_s = input().strip().split()
    print(calculate_invoice(t_s, float(a_s)))

