import json

def strict_int(v):
    return isinstance(v, int) and not isinstance(v, bool)

def valid_email(s):
    if not isinstance(s, str) or " " in s or s.count("@") != 1:
        return False
    local, dom = s.split("@")
    return bool(local) and "." in dom and not dom.startswith(".") and not dom.endswith(".")

n = int(input().strip())
valid = 0
reasons = []

for idx in range(1, n + 1):
    raw = input().strip()
    try:
        obj = json.loads(raw)
    except json.JSONDecodeError:
        reasons.append(f"{idx}:BAD_JSON")
        continue
    if not isinstance(obj, dict):
        reasons.append(f"{idx}:BAD_JSON")
    elif not strict_int(obj.get("id")) or obj["id"] <= 0:
        reasons.append(f"{idx}:BAD_ID")
    elif not valid_email(obj.get("email")):
        reasons.append(f"{idx}:BAD_EMAIL")
    elif not strict_int(obj.get("age")) or not (13 <= obj["age"] <= 120):
        reasons.append(f"{idx}:BAD_AGE")
    else:
        valid += 1

print(f"Valid:{valid} Rejected:{len(reasons)}")
print("RejectedReasons: " + (", ".join(reasons) if reasons else "NONE"))

import json

p_cnt = int(input().strip())
pages = [json.loads(input().strip()) for _ in range(p_cnt)]
pages.sort(key=lambda pg: pg.get("page", 0))

merged = {}
for pg in pages:
    for item in (pg.get("results") or []):
        if not isinstance(item, dict) or "id" not in item:
            continue
        iid = str(item["id"])
        prio = item.get("priority")
        if not isinstance(prio, int) or isinstance(prio, bool):
            prio = 0
        tags = item.get("tags")
        if not isinstance(tags, list):
            tags = []
        merged[iid] = (prio, [str(t) for t in tags])

if not merged:
    print("EMPTY")
else:
    ordered = sorted(merged.items(), key=lambda kv: (-kv[1][0], kv[0]))
    for iid, (prio, tags) in ordered:
        t_str = ",".join(tags) if tags else "NONE"
        print(f"{iid} | prio={prio} | tags={t_str}")

