import csv
import io

n = int(input().strip())
csv_text = "\n".join(input().rstrip("\n") for _ in range(n))
reader = csv.DictReader(io.StringIO(csv_text))

totals = {}
for row in reader:
    cat = (row.get("category") or "").strip()
    if not cat:
        continue
    try:
        units = int(row["units"])
        price = float(row["price"])
        cost = float(row["cost"])
    except (TypeError, ValueError, KeyError):
        continue
    if units <= 0 or price < 0 or cost < 0:
        continue
    rev = units * price
    prof = units * (price - cost)
    prev_r, prev_p = totals.get(cat, (0.0, 0.0))
    totals[cat] = (prev_r + rev, prev_p + prof)

if not totals:
    print("NO_DATA")
else:
    for cat in sorted(totals):
        rev, prof = totals[cat]
        margin = (prof / rev * 100.0) if rev > 0 else 0.0
        print(f"{cat}: Revenue={rev:.2f} Profit={prof:.2f} Margin={margin:.1f}%")

