import heapq

k = int(input().strip())
streams = []
for _ in range(k):
    raw = input().strip()
    if raw and raw != "NONE":
        streams.append([int(x) for x in raw.split()])

heap = []
for s_idx, st in enumerate(streams):
    if st:
        heapq.heappush(heap, (st[0], s_idx, 0))

out = []
while heap:
    val, s_idx, pos = heapq.heappop(heap)
    out.append(str(val))
    nxt = pos + 1
    if nxt < len(streams[s_idx]):
        heapq.heappush(heap, (streams[s_idx][nxt], s_idx, nxt))

print(" ".join(out) if out else "EMPTY")

import io
import unittest

def valid_discount(price, pct):
    if price < 0 or not (0 <= pct <= 100):
        raise ValueError("out of bounds")
    return round(price * (1.0 - pct / 100.0), 2)

def buggy_discount(price, pct):
    if price < 0 or pct < 0:
        raise ValueError("missing upper bound")
    return round(price * (1.0 - pct / 100.0), 2)

mode = input().strip()
target_fn = valid_discount if mode == "TEST_VALID" else buggy_discount

class TestDiscountSuite(unittest.TestCase):
    def test_normal(self):
        self.assertEqual(target_fn(200.0, 15.0), 170.0)

    def test_boundaries(self):
        self.assertEqual(target_fn(99.95, 0.0), 99.95)
        self.assertEqual(target_fn(99.95, 100.0), 0.0)

    def test_negative_price(self):
        with self.assertRaises(ValueError):
            target_fn(-1.0, 10.0)

    def test_over_discount(self):
        with self.assertRaises(ValueError):
            target_fn(50.0, 120.0)

suite = unittest.TestLoader().loadTestsFromTestCase(TestDiscountSuite)
res = unittest.TextTestRunner(stream=io.StringIO(), verbosity=0).run(suite)
fails = len(res.failures) + len(res.errors)
status = "PASS" if res.wasSuccessful() else "FAIL"
print(f"TestsRun:{res.testsRun} | Failures:{fails} | Suite:{status}")

