def make_batch(name, items=None):
    clean = [] if items is None else sorted(set(t for t in items if t))
    return f"Batch({name}): " + (",".join(clean) if clean else "NONE")

def is_monotonic(nums):
    for i in range(len(nums) - 1):
        if nums[i] > nums[i + 1]:
            return False
    return True

