def oracle(arr, k):
    cnt = 0
    n = len(arr)
    for i in range(n):
        s = 0
        for j in range(i, n):
            s += arr[j]
            if s == k:
                cnt += 1
    return cnt

def fast_buggy(arr, k):
    cnt = s = l = 0
    for r, x in enumerate(arr):
        s += x
        while l <= r and s > k:
            s -= arr[l]
            l += 1
        if l <= r and s == k:
            cnt += 1
    return cnt

def fast_fixed(arr, k):
    seen = {0: 1}
    s = cnt = 0
    for x in arr:
        s += x
        cnt += seen.get(s - k, 0)
        seen[s] = seen.get(s, 0) + 1
    return cnt

mode = input().strip()
solver = fast_fixed if mode == "FIXED" else fast_buggy
q = int(input().strip())

mismatches = 0
first_bad = "NONE"
for idx in range(1, q + 1):
    arr_s, k_s = input().strip().split("|")
    arr = [int(x) for x in arr_s.split()]
    k = int(k_s.strip())
    if oracle(arr, k) != solver(arr, k):
        mismatches += 1
        if first_bad == "NONE":
            first_bad = str(idx)

verdict = "VERIFIED" if mismatches == 0 else "DEFECTIVE"
print(f"Cases:{q} | Mismatches:{mismatches} | FirstMismatch:{first_bad} | Verdict:{verdict}")
